// C++98 style code demonstrating the problem

// typedefs for clarity in C++98
typedef std::vector<int>::iterator IterT;
typedef std::vector<int>::const_iterator ConstIterT;

std::vector<int> values;
// ... populate values

// Problem 1: Hard to get a const_iterator from a non-const container
// Requires a cast to get const_iterator for a find operation
ConstIterT ci = std::find(static_cast<ConstIterT>(values.begin()),
                            static_cast<ConstIterT>(values.end()),
                            1983);

// Problem 2: Can't use a const_iterator for mutation
// The line below would not compile in C++98
// values.insert(ci, 1998); // Error: insert expects iterator

// A non-portable and unsafe workaround attempt
values.insert(static_cast<IterT>(ci), 1998); // May not compile
